<body>
  <main class="page-shell">
    <section class="preview-card" aria-labelledby="image-title">
      <div class="image-panel">
        <img
          src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=85"
          alt="A bright modern living room with large windows and warm wooden furniture"
        >
      </div>

      <div class="details-panel">
        <div>
          <p class="eyebrow">Library preview</p>
          <h1 id="image-title">Sunlit Loft Interior</h1>
          <p class="description">
            A curated image from your design inspiration library. Review the asset details
            or remove it from your collection when it no longer fits your project.
          </p>

          <div class="meta-grid" aria-label="Image details">
            <div class="meta-item">
              <span class="meta-label">Format</span>
              <span class="meta-value">JPG</span>
            </div>
            <div class="meta-item">
              <span class="meta-label">Size</span>
              <span class="meta-value">4.8 MB</span>
            </div>
            <div class="meta-item">
              <span class="meta-label">Added</span>
              <span class="meta-value">Today</span>
            </div>
            <div class="meta-item">
              <span class="meta-label">Collection</span>
              <span class="meta-value">Interiors</span>
            </div>
          </div>
        </div>

        <div class="actions">
          <button class="button button-secondary" type="button">Download</button>
          <button class="button trigger" type="button" aria-haspopup="dialog">
            Delete image
          </button>
        </div>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-card">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
        This will remove "Sunlit Loft Interior" from your library. This action cannot be undone.
      </p>

      <form method="dialog" class="dialog-actions">
        <button class="button button-ghost" value="cancel" type="submit">Cancel</button>
        <button class="button button-danger" id="confirm-delete" value="delete" type="submit">
          Yes, delete it
        </button>
      </form>
    </div>
  </dialog>

  <div class="toast" role="status" aria-live="polite"></div>

  <script>
    const deleteDialog = document.querySelector("#delete-dialog");
    const deleteTrigger = document.querySelector(".trigger");
    const confirmDelete = document.querySelector("#confirm-delete");
    const toast = document.querySelector(".toast");

    deleteTrigger.addEventListener("click", () => {
      deleteDialog.showModal();
    });

    confirmDelete.addEventListener("click", () => {
      toast.textContent = "Image deleted from your library.";
      toast.classList.add("is-visible");

      window.setTimeout(() => {
        toast.classList.remove("is-visible");
      }, 2800);
    });
  </script>
</body>
</html>
